def put(self, k, v):
    self.d[k] = v
    self.d.move_to_end(k)
    if len(self.d) > self.cap:
        self.d.popitem(last=False)

def get(self, k):
    v, exp = self.d.get(k, (None, 0))
    if self.now() >= exp:
        self.d.pop(k, None); return None
    return v
